'use strict';

// MAIN //

/**
* Escapes special characters in a string for bash environment variables.
*
* @private
* @param {string} str - input string
* @returns {string} escaped string
*
* @example
* var escaped = escapeBashString( "Spence's function" );
* // returns "Spence'\\''s function"
*/
function escapeBashString( str ) {
	return str.replace( /'/g, "'\\''" ).replace( /\n/g, '\\n' );
}


// EXPORTS //

module.exports = escapeBashString;
